import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('conocimiento-verdadero-ii', 'C',
 [dict(t=1481, e=1537, titulo='Sin revelación no hay discernimiento', txt='No hay revelación, no hay discernimiento. Hay que pedir discernimiento de espíritu para ver quién nos habla. […] Hasta el tercer día se dio cuenta Pablo de que era una pitonisa, una mujer falsa. Y a veces nosotros, hermano, caemos en lo mismo por no tener discernimiento. […] Puede llegar tarde, y puede destruir tu vida.'),
  dict(t=2462, e=2515, titulo='La llave del conocimiento', txt='«Porque habéis quitado la llave del conocimiento.» Mire qué tremendo, hermano. Dios esta noche nos está regalando esa llave para tu vida. ¿Cuántos la quieren? Yo quiero saber más de Dios cada día. Hay gente que no sabe nada, hermanos: se viene a sentar y no apunta, no se le queda nada. Vaya a su casa a revisar, vaya a su casa a orar, a interceder, y esa Palabra, en vez de ver su serie de novela, ore.'),
  dict(t=3604, e=3652, titulo='Mar adentro está lo profundo', txt='¿Dónde se agarran los dichos profundos? ¿Qué hacía el Señor cuando predicaba a la multitud? Se retiraba y ponía agua entre ellos y el Señor. Y después, cuando terminaba el discurso, les decía a los discípulos: «Boga mar adentro; te voy a enseñar las poderosas cosas del evangelio que te van a servir.» No están aquí en la orilla, no están aquí en la arena, en la humanidad: están ahí adentro. Y se los llevaba, y allá aprendieron un montón.')],
 [dict(t=2238, txt='Sí, son lindos, pero es más lindo Dios. Y tú no has venido a cuidar perros solamente, sino que has venido a hacer la promesa de Dios en tu vida.'),
  dict(t=2916, txt='Esa es la ventaja de cubrirte con las alas del amor, porque eso te da equilibrio.'),
  dict(t=4129, txt='No vamos a poder decirle: «Es que yo no tenía quién me ayudara.» No: tienes todas estas armas de luz. Ponte la armadura de Dios, que está en Efesios 6.')],
 ['«No hay revelación, no hay discernimiento.» ¿Qué le pides hoy a Dios para ver con claridad quién te está hablando y qué debes decidir?',
  'Jesús reprochó a los que quitaron «la llave del conocimiento». ¿Qué hábito concreto puedes empezar para que la Palabra se te quede esta semana?',
  'El Señor se retiraba de la multitud para enseñar «mar adentro». ¿Qué te impide hoy ir más profundo con Él?'],
 inicio=399)
